css:
[data-bz-node="header"] { position: sticky; top: 0; z-index: 60; border-bottom: 1px solid var(--line); box-shadow: 0 1px 0 rgb(15 23 42 / 4%); }
[data-bz-node="main-nav"] .bz-nav { gap: var(--space-1); }
[data-bz-node="main-nav"] .bz-nav > .bz-navitem > a { font-size: 16px; text-transform: uppercase; letter-spacing: .04em; padding: var(--space-3) var(--space-4); border-radius: var(--radius-nav); color: var(--ink); transition: color .15s ease, background-color .15s ease; }
[data-bz-node="main-nav"] .bz-nav > .bz-navitem > a:hover,
[data-bz-node="main-nav"] .bz-nav > .bz-navitem--has-sub:hover > a,
[data-bz-node="main-nav"] .bz-nav > .bz-navitem--has-sub:focus-within > a { color: var(--accent); background: var(--paper); }
[data-bz-node="main-nav"] .bz-subnav .bz-subnav a { font-weight: 500; font-size: 15px; color: var(--ink); transition: color .15s ease; }
[data-bz-node="main-nav"] .bz-subnav .bz-subnav a:hover { color: var(--accent); }
[data-bz-node="header-button"] .bz-btn { white-space: nowrap; background: var(--accent); border-color: var(--accent); color: #fff; }
[data-bz-node="header-button"] .bz-btn:hover { background: var(--accent-dark); border-color: var(--accent-dark); color: #fff; }

/* Mega panels hang from the nav block itself, not from the whole header, so a
   panel lines up under its menu and can never run past the container edge. */
@media (min-width: 1101px) {
  [data-bz-node="main-nav"] .bz-menu--mega { position: relative; }
  [data-bz-node="main-nav"] .bz-menu--mega .bz-nav > .bz-navitem--has-sub { position: static; }
  [data-bz-node="main-nav"] .bz-menu--mega .bz-nav > .bz-navitem--has-sub > .bz-subnav {
    top: calc(100% + 8px); left: 0; right: 0; width: auto; max-width: none;
    justify-content: flex-start; gap: var(--space-7);
    padding: var(--space-6) var(--space-6) var(--space-5);
    border: 1px solid var(--line); border-top: 3px solid var(--accent); border-radius: 0 0 var(--radius-card) var(--radius-card);
    box-shadow: 0 18px 40px rgb(15 23 42 / 14%);
    /* Fade + slide instead of display toggling, so it can animate. */
    display: flex; visibility: hidden; opacity: 0; pointer-events: none;
    transform: translateY(8px);
    transition: opacity .2s ease, transform .2s ease, visibility 0s linear .2s;
  }
  [data-bz-node="main-nav"] .bz-menu--mega .bz-nav > .bz-navitem--has-sub:hover > .bz-subnav,
  [data-bz-node="main-nav"] .bz-menu--mega .bz-nav > .bz-navitem--has-sub:focus-within > .bz-subnav,
  [data-bz-node="main-nav"] .bz-menu--mega .bz-nav > .bz-navitem--has-sub[data-open] > .bz-subnav {
    visibility: visible; opacity: 1; pointer-events: auto; transform: translateY(0);
    transition: opacity .2s ease, transform .2s ease, visibility 0s;
  }
  /* The bridge: an invisible strip over the 8px gap (and a little more), part
     of the panel and so part of the hovered item. The pointer never leaves the
     :hover container on its way from the trigger down into the panel. */
  [data-bz-node="main-nav"] .bz-menu--mega .bz-nav > .bz-navitem--has-sub > .bz-subnav::before {
    content: ""; position: absolute; left: 0; right: 0; bottom: 100%; height: 14px;
  }
  /* And under the trigger itself, while it is hovered, down to the panel. */
  [data-bz-node="main-nav"] .bz-nav > .bz-navitem--has-sub > a { position: relative; }
  [data-bz-node="main-nav"] .bz-nav > .bz-navitem--has-sub:hover > a::after {
    content: ""; position: absolute; left: 0; right: 0; top: 100%; height: 24px;
  }
  [data-bz-node="main-nav"] .bz-subnav > .bz-navitem > .bz-navlabel { color: var(--ink); font: 700 15px / 1.2 var(--font-heading); letter-spacing: .02em; text-transform: none; }
}
@media (min-width: 1101px) and (prefers-reduced-motion: reduce) {
  [data-bz-node="main-nav"] .bz-menu--mega .bz-nav > .bz-navitem--has-sub > .bz-subnav { transform: none; transition: none; }
}
[data-bz-node="footer"] a:not(.bz-btn) { color: rgba(255,255,255,.82); }
[data-bz-node="footer"] a:not(.bz-btn):hover { color: #fff; }
@media (max-width: 1100px) {
  [data-bz-node="main-nav"] .bz-menu-wrap[data-open] > .bz-menu { max-height: calc(100vh - 140px); overflow-y: auto; }
  [data-bz-node="main-nav"] .bz-nav > .bz-navitem > a { padding-block: var(--space-2); }
}
@media (max-width: 640px) {
  [data-bz-node="logo"] .bz-logo__img { height: 34px; }
  [data-bz-node="header-button"] .bz-btn { padding-inline: var(--space-3); font-size: 14px; }
}
